import pytest

import sqlparse
from sqlparse import filters, sql, tokens as T


@pytest.mark.parametrize('output_format, prefix, quote, suffix', [
    ('python', '', "'", ''),
    ('php', '$', '"', ';'),
])
@pytest.mark.parametrize('statement_count', [1, 2, 3, 12])
def test_statement_names(output_format, prefix, quote, suffix, statement_count):
    statements = [f'select {i};' for i in range(1, statement_count + 1)]
    expected = []
    for i, statement in enumerate(statements, 1):
        varname = prefix + ('sql' if i == 1 else f'sql{i}')
        if i < statement_count:
            statement += ' '
        expected.append(f'{varname} = {quote}{statement}{quote}{suffix}')
    expected = '\n'.join(expected)
    query = ' '.join(statements)

    assert sqlparse.format(query, output_format=output_format) == expected
    # A fresh formatting call must start numbering from the unsuffixed name.
    assert sqlparse.format(query, output_format=output_format) == expected
    if output_format == 'python':
        namespace = {}
        exec(expected, namespace)
        for i, statement in enumerate(statements, 1):
            varname = 'sql' if i == 1 else f'sql{i}'
            assert namespace[varname] == statement + (
                ' ' if i < statement_count else '')


@pytest.mark.parametrize('filter_cls, prefix, quote, suffix', [
    (filters.OutputPythonFilter, '', "'", ''),
    (filters.OutputPHPFilter, '$', '"', ';'),
])
@pytest.mark.parametrize('varname', ['q', 'sql', 'query'])
def test_custom_variable_names(filter_cls, prefix, quote, suffix, varname):
    output_filter = filter_cls(varname)
    for i in range(1, 4):
        statement = sqlparse.parse(f'select {i};')[0]
        name = prefix + varname + (str(i) if i > 1 else '')
        expected = f'{name} = {quote}select {i};{quote}{suffix}'
        if i > 1:
            expected = '\n' + expected
        assert str(output_filter.process(statement)) == expected


@pytest.mark.parametrize('filter_cls', [
    filters.OutputPythonFilter,
    filters.OutputPHPFilter,
])
@pytest.mark.parametrize('varname', ['q', 'sql', 'query'])
def test_multiline_indentation(filter_cls, varname):
    statement = sql.Statement([
        sql.Token(T.Text, 'select *'),
        sql.Token(T.Whitespace, '\n  '),
        sql.Token(T.Text, 'from foo;'),
    ])
    output_tokens = list(filter_cls(varname).process(statement).tokens)
    result = ''.join(token.value for token in output_tokens)

    if filter_cls is filters.OutputPythonFilter:
        expected = (f"{varname} = ('select * '\n"
                    + ' ' * (len(varname) + 4) + "'  from foo;')")
        namespace = {}
        exec(result, namespace)
        assert namespace[varname] == 'select *   from foo;'
    else:
        expected = (f'${varname}  = "select * ";\n'
                    f'${varname} .= "  from foo;";')
    assert result == expected
    assert any(token.ttype is T.Whitespace and token.value == '  '
               for token in output_tokens)


@pytest.mark.parametrize('output_format, expected', [
    ('python', r'''sql = 'select \'it\'\'s "foo"\';' '''.rstrip()),
    ('php', r'''$sql = "select 'it''s \"foo\"';";'''),
])
@pytest.mark.parametrize('reindent', [False, True])
def test_quoted_literals(output_format, expected, reindent):
    query = '''select 'it''s "foo"';'''
    result = sqlparse.format(query, output_format=output_format,
                             reindent=reindent)
    assert result == expected
    if output_format == 'python':
        namespace = {}
        exec(result, namespace)
        assert namespace['sql'] == query


@pytest.mark.parametrize('output_format', ['python', 'php'])
@pytest.mark.parametrize('reindent', [False, True])
def test_empty_input(output_format, reindent):
    assert sqlparse.format('', output_format=output_format,
                           reindent=reindent) == ''
